import time
left = int(max_items if max_items is not None else 20)
if left < 1:
    raise ValueError("max_items must be at least 1.")
budget = float(budget_s if budget_s is not None else 90)
now = time.time()
return {"updates": {"drain_deadline": now + budget, "drain_left": left, "drain_continue": True,
        "drain_processed": 0, "drain_failed": 0, "drain_errors": [], "drain_requeued": [],
        "drain_worker": "drain-" + str(int(now * 1000))}}

arguments = {}
if worker_id is not None and worker_id != "":
    arguments["worker_id"] = worker_id
if max_items is not None and max_items != "":
    arguments["max_items"] = max_items
return {"tool_calls": [{"name": "note_queue_lease", "call_id": "lease", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
failure = None
out = None
if not isinstance(r, dict):
    failure = "note_queue_lease returned no result."
elif not r.get("success"):
    failure = str(r.get("error") or "note_queue_lease failed.")
else:
    out = r.get("output")
    if not isinstance(out, dict):
        failure = "note_queue_lease returned something other than an object."
if failure is not None:
    return {"failed": True, "failure": failure}
return dict(out, tool_output=out, failed=False, failure=None)

o = output if isinstance(output, dict) else {}
c = child_output if isinstance(child_output, dict) else {}
err = str(c.get("error") or o.get("error") or "")
for prefix in ("Runtime error: ", "Execution error: "):
    if err.startswith(prefix):
        err = err[len(prefix):]
rev = o.get("revision") if isinstance(o.get("revision"), dict) else {}
if not err and c.get("success") is not False and rev.get("requeue"):
    # the notebook changed while the note was read: nothing was applied, it goes back once (review 4.1)
    return {"outcome": "requeue", "failure": str(rev.get("reason") or ""), "revision_id": None}
failed = c.get("success") is False or o.get("success") is False or bool(err) or not o.get("revision_id")
return {"outcome": "error" if failed else "ok",
        "failure": (str(err) if err else "The note could not be processed.") if failed else None,
        "revision_id": None if failed else o.get("revision_id")}

arguments = {}
if note_id is not None and note_id != "":
    arguments["note_id"] = note_id
if outcome is not None and outcome != "":
    arguments["outcome"] = outcome
if error is not None and error != "":
    arguments["error"] = error
if revision_id is not None and revision_id != "":
    arguments["revision_id"] = revision_id
return {"tool_calls": [{"name": "note_queue_ack", "call_id": "ack", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
failure = None
out = None
if not isinstance(r, dict):
    failure = "note_queue_ack returned no result."
elif not r.get("success"):
    failure = str(r.get("error") or "note_queue_ack failed.")
else:
    out = r.get("output")
    if not isinstance(out, dict):
        failure = "note_queue_ack returned something other than an object."
if failure is not None:
    return {"failed": True, "failure": failure}
return dict(out, tool_output=out, failed=False, failure=None)

arguments = {}
if only_if_due is not None and only_if_due != "":
    arguments["only_if_due"] = only_if_due
return {"tool_calls": [{"name": "note_communities_recompute", "call_id": "communities", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
failure = None
out = None
if not isinstance(r, dict):
    failure = "note_communities_recompute returned no result."
elif not r.get("success"):
    failure = str(r.get("error") or "note_communities_recompute failed.")
else:
    out = r.get("output")
    if not isinstance(out, dict):
        failure = "note_communities_recompute returned something other than an object."
if failure is not None:
    return {"failed": True, "failure": failure}
return dict(out, tool_output=out, failed=False, failure=None)

n = int(processed or 0)
k = int(failed or 0)
back = list(requeued or [])
if n == 0 and k == 0 and not back:
    msg = "Nothing to process."
else:
    msg = "Processed " + str(n) + (" note." if n == 1 else " notes.")
    if k:
        msg = msg[:-1] + "; " + str(k) + (" could not be processed." if k > 1 else " could not be processed.")
    if back:
        b = len(back)
        msg += " " + str(b) + (" note is" if b == 1 else " notes are") + " read again: the notebook changed while"
        msg += (" it was" if b == 1 else " they were") + " being read."
c = dict(themes) if isinstance(themes, dict) else {}
if themes_failed:
    c = {"recomputed": False, "error": str(themes_failure or "")}
    msg += " The themes could not be updated: " + str(themes_failure or "no reason was given.")
elif c.get("recomputed"):
    g = int(c.get("communities") or 0)
    w = int(c.get("labels_waiting") or 0)
    msg += " The themes were updated (" + str(g) + (" group" if g == 1 else " groups")
    msg += ((", " + str(w) + " to name next time).") if w else ").")
return {"message": msg, "processed": n, "failed": k, "errors": list(errors or []), "communities": c,
        "requeued": back}
